output_text:
[
  {
    "id": "no_carts_in_shelf_canyons",
    "text": "Shopping carts are prohibited in single-file aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "two_sided_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "two_sided_shelf_aisle",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_canyon",
    "text": "A shopper must not move a cart into a single-file shelf canyon.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "push_cart_into_single_file_aisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_into_single_file_aisle"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or lets go of a cart, they are obliged to retrieve a cart before finishing.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "set_down_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recover_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "set_down_cart",
      "discharge": "recover_cart"
    }
  },
  {
    "id": "park_only_in_wide_staging_area",
    "text": "Carts may only be parked in wide, non-shelf-adjacent staging areas rather than beside shelves or in narrow aisles.",
    "abstraction": {
      "state_properties": {
        "wide_cart_staging_zone": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "set_down_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "set_down_cart",
          {
            "not": "wide_cart_staging_zone"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_service_requires_cart",
    "text": "Shelf interactions from wide cart-compatible aisles require the shopper to have a cart.",
    "abstraction": {
      "state_properties": {
        "wide_shelf_service_zone": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wide_shelf_service_zone",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_pickups_on_foot",
    "text": "When interacting with items in a single-file shelf aisle, the shopper must be on foot rather than holding a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "single_file_shelf_aisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cartless_only_in_allowed_zones",
    "text": "After entering the shop floor, being without a cart is allowed only at the entrance/cart bay, in wide cart-staging zones, or inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "entrance_or_cart_bay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "wide_cart_staging_zone": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartless_exception_area": {
          "or": [
            "entrance_or_cart_bay",
            "wide_cart_staging_zone",
            "single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartless_exception_area"
          }
        ]
      }
    }
  },
  {
    "id": "return_from_canyon_to_cart",
    "text": "A shopper who enters a single-file shelf aisle without a cart is obliged to return to and recover the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_without_cart": {
          "pre": {
            "and": [
              {
                "not": "single_file_shelf_aisle"
              },
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        },
        "recover_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_single_file_without_cart",
      "discharge": "recover_cart"
    }
  }
]
